INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 1, "あたしだって\nやるときはやるよ！", 1, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24001, "リン", 0, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 1, "ふぅ…\nこれであたしの仕事は\n終わりだね", 1, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24002, "リン", 1, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 1, "終わった終わった\n一人でもなんとか\nなるもんだね", 1, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24003, "リン", 2, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 2, "やったね！\nこれでようやく\nサボれるよ…", 2, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24004, "リン", 3, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 1, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 1, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24005, "リン", 4, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 2, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 2, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24006, "リン", 5, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 2, "あたしも意外と\nやるもんでしょ？", 2, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24007, "リン", 6, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 4, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 4, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24008, "リン", 7, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 4, "このままじゃ\nまっひ～に\n叱られちゃうよ", 4, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24009, "リン", 8, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 4, "まじめに\nやったんだけどな…\n悔しいな～", 4, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24010, "リン", 9, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 4, "やられた…\nねずみって意外と\nてごわいね", 4, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24011, "リン", 10, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 4, "おのれ～\nあたしのチーズを\n盗みやがって～！", 4, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 0.0, 102601, 10040, 0.0, 24012, "リン", 11, 24);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES (0.0, 1, "疲れた…\nけど、次こそは\n守り抜くよ…", 4, "2030/12/17 14:59:59", "2020/04/30 12:00:00", 1.81, 102601, 10040, 0.0, 24013, "リン", 12, 24);
